type Analytics = {
  pageViews: number;
  uniqueVisitors: number;
  averageSessionDuration: number;
  bounceRate: number;
  topPages: Array<{ page: string; views: number }>;
};

type Notification = {
  id: number;
  message: string;
  timestamp: string;
  read: boolean;
};

type Notifications = {
  unreadCount: number;
  items: Notification[];
};

type Settings = {
  theme: string;
  language: string;
  notifications: {
    email: boolean;
    push: boolean;
    sms: boolean;
  };
  privacy: {
    profileVisible: boolean;
    showEmail: boolean;
  };
  displayName: string;
  timezone: string;
};

async function getDashboardData() {
  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch('http://localhost:3000/api/analytics').then(r => r.json()),
      fetch('http://localhost:3000/api/notifications').then(r => r.json()),
      fetch('http://localhost:3000/api/settings').then(r => r.json())
    ]);

    return { analytics, notifications, settings };
  } catch {
    return {
      analytics: {
        pageViews: 0,
        uniqueVisitors: 0,
        averageSessionDuration: 0,
        bounceRate: 0,
        topPages: []
      },
      notifications: {
        unreadCount: 0,
        items: []
      },
      settings: {
        theme: 'light',
        language: 'en',
        notifications: { email: false, push: false, sms: false },
        privacy: { profileVisible: true, showEmail: false },
        displayName: 'User',
        timezone: 'UTC'
      }
    };
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData();

  return (
    <div>
      <h2>Dashboard Content</h2>

      <section>
        <h3>Analytics</h3>
        <p>Page Views: {analytics.pageViews.toLocaleString()}</p>
        <p>Unique Visitors: {analytics.uniqueVisitors.toLocaleString()}</p>
        <p>Avg Session Duration: {analytics.averageSessionDuration}s</p>
        <p>Bounce Rate: {analytics.bounceRate}%</p>
        <h4>Top Pages:</h4>
        <ul>
          {analytics.topPages.map((page, index) => (
            <li key={index}>
              {page.page}: {page.views.toLocaleString()} views
            </li>
          ))}
        </ul>
      </section>

      <section>
        <h3>Notifications ({notifications.unreadCount} unread)</h3>
        <ul>
          {notifications.items.slice(0, 3).map((notif) => (
            <li key={notif.id} style={{ fontWeight: notif.read ? 'normal' : 'bold' }}>
              {notif.message}
            </li>
          ))}
        </ul>
      </section>

      <section>
        <h3>Settings</h3>
        <p>Display Name: {settings.displayName}</p>
        <p>Theme: {settings.theme}</p>
        <p>Language: {settings.language}</p>
        <p>Email Notifications: {settings.notifications.email ? 'On' : 'Off'}</p>
      </section>
    </div>
  );
}

